code.C:
#include <stdio.h>
#include <string.h>
int main() {
    char s[1005]; if (scanf("%s", s) != 1) return 0;
    int l = 0, r = strlen(s) - 1, pal = 1;
    while (l < r) { if (s[l++] != s[r--]) { pal = 0; break; } }
    printf("%s\n", pal ? "Yes" : "No");
    return 0;
}

